tent":[{"type":"paragraph","attrs":{"align":null},"content":[{"type":"text","text":"GPIO20 / GPIO21"}]}]},{"type":"table_cell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"align":null},"content":[{"type":"text","text":"DFPlayer RX / TX"}]}]},{"type":"table_cell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"align":null},"content":[{"type":"text","text":"UART1，RX 串 1kΩ"}]}]}]},{"type":"table_row","content":[{"type":"table_cell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"align":null},"content":[{"type":"text","text":"5V / GND"}]}]},{"type":"table_cell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"align":null},"content":[{"type":"text","text":"各模块"}]}]},{"type":"table_cell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"align":null},"content":[{"type":"text","text":"务必共地"}]}]}]}]},{"type":"callout","attrs":{"type":"warning"},"content":[{"type":"paragraph","attrs":{"align":null},"content":[{"type":"text","text":"TB6612 的 "},{"type":"text","marks":[{"type":"code"}],"text":"VM"},{"type":"text","text":" 接电机电源（电池），"},{"type":"text","marks":[{"type":"code"}],"text":"VCC"},{"type":"text","text":" 接 3.3V 逻辑，"},{"type":"text","marks":[{"type":"code"}],"text":"STBY"},{"type":"text","text":" 必须拉高；DFPlayer 的 RX 串 1kΩ 再接 C3 的 TX；所有 GND 共地。具体 GPIO 以你手上的 C3 板为准，可用软串口扩展。"}]}]},{"type":"heading","attrs":{"level":2,"align":null},"content":[{"type":"text","text":"六、示例程序"}]},{"type":"heading","attrs":{"level":3,"align":null},"content":[{"type":"text","text":"路线 A：离线语音（SU-03T 命令 ID → 电机）"}]},{"type":"code_block","attrs":{"language":"cpp"},"content":[{"type":"text","text":"#include <SoftwareSerial.h>\n#include <DFRobotDFPlayerMini.h>\n#include <FastLED.h>\n\n#define AIN1 0\n#define AIN2 1\n#define PWMA 2\n#define BIN1 5\n#define BIN2 6\n#define PWMB 7\n#define STBY 9\n#define LED_PIN 8\n#define NUM_LEDS 8\n#define SPEED 180            // 0-255，给宝宝调慢！\n\nSoftwareSerial voice(3, 4);  // RX=3, TX=4 → SU-03T\nCRGB leds[NUM_LEDS];\n\nvoid motor(int l, int r) {    // 左右轮速度 -255~255\n  digitalWrite(AIN1, l >= 0); digitalWrite(AIN2, l < 0);\n  digitalWrite(BIN1, r >= 0); digitalWrite(BIN2, r < 0);\n  ledcWrite(0, abs(l)); ledcWrite(1, abs(r));\n}\nvoid forward() { motor(SPEED, SPEED); }\nvoid back()    { motor(-SPEED, -SPEED); }\nvoid left()    { motor(-SPEED, SPEED); }\nvoid right()   { motor(SPEED, -SPEED); }\nvoid stop()    { motor(0, 0); }\n\nvoid setup() {\n  for (auto p : {AIN1,AIN2,PWMA,BIN1,BIN2,PWMB,STBY}) pinMode(p, OUTPUT);\n  digitalWrite(STBY, HIGH);\n  ledcSetup(0, 20000, 8); ledcAttachPin(PWMA, 0);\n  ledcSetup(1, 20000, 8); ledcAttachPin(PWMB, 1);\n  FastLED.addLeds<WS2812, LED_PIN, GRB>(leds, NUM_LEDS);\n  voice.begin(9600);\n}\n\nvoid loop() {\n  if (voice.available()) {\n    int id = voice.parseInt();   // SU-03T 吐出的命令 ID\n    switch (id) {\n      case 1: forward(); break;  // “前进”\n      case 2: back();    break;  // “后退”\n      case 3: left();    break;  // “左转”\n      case 4: right();   break;  // “右转”\n      case 5: stop();    break;  // “停”\n    }\n    fill_solid(leds, NUM_LEDS, CRGB::Green);\n    FastLED.show();\n  }\n}"}]},{"type":"heading","attrs":{"level":3,"align":null},"content":[{"type":"text","text":"路线 B：C3 直连大模型 API（把话问给 LLM，拿回指令）"}]},{"type":"paragraph","attrs":{"align":null},"content":[{"type":"text","text":"下面用 "},{"type":"text","marks":[{"type":"code"}],"text":"WiFiClientSecure"},{"type":"text","text":" + "},{"type":"text","marks":[{"type":"code"}],"text":"HTTPClient"},{"type":"text","text":" + "},{"type":"text","marks":[{"type":"code"}],"text":"ArduinoJson"},{"type":"text","text":" 演示：SU-03T 给到识别文本后，C3 直接 POST 给大模型，要求只回 JSON 指令，再解析执行。模型可换 DeepSeek / 通义 / OpenAI，或家里 Ollama 的局域网地址。"}]},{"type":"code_block","attrs":{"language":"cpp"},"content":[{"type":"text","text":"#include <WiFi.h>\n#include <WiFiClientSecure.h>\n#include <HTTPClient.h>\n#include <ArduinoJson.h>\n\nconst char* SSID = \"你的WiFi\";\nconst char* PASS = \"密码\";\n// 云端：https://api.deepseek.com/chat/completions\n// 本地：http://192.168.x.x:11434/api/chat  （Ollama）\nconst char* API  = \"https://api.deepseek.com/chat/completions\";\nconst char* KEY  = \"sk-xxxx\";\n\nWiFiClientSecure client;\nHTTPClient http;\n\n// 把 SU-03T 识别到的文本发给大模型，返回动作 JSON 字符串\nString askLLM(String saying) {\n  DynamicJsonDocument req(512);\n  req[\"model\"] = \"deepseek-chat\";\n  req[\"response_format\"][\"type\"] = \"json_object\";\n  JsonArray msgs = req.createNestedArray(\"messages\");\n  JsonObject sys = msgs.createNestedObject();\n  sys[\"role\"] = \"system\";\n  sys[\"content\"] = \"你是玩具小车。把用户的话转成JSON:{\\\"action\\\":\\\"forward|back|left|right|stop|music\\\",\\\"seconds\\\":int}。只输出JSON。\";\n  JsonObject usr = msgs.createNestedObject();\n  usr[\"role\"] = \"user\";\n  usr[\"content\"] = saying;\n  String body;\n  serializeJson(req, body);\n\n  http.begin(client, API);\n  http.addHeader(\"Content-Type\", \"application/json\");\n  http.addHeader(\"Authorization\", String(\"Bearer \") + KEY);\n  http.POST(body);\n  String resp = http.getString();\n  http.end();\n\n  DynamicJsonDocument res(512);\n  deserializeJson(res, resp);\n  return res[\"choices\"][0][\"message\"][\"content\"].as<String>(); // 形如 {\"action\":\"forward\",\"seconds\":2}\n}\n\nvoid loop() {\n  if (voice.available()) {\n    String saying = readSU03TText();   // SU-03T 给到的识别文本\n    String cmd = askLLM(saying);       // C3 直接问大模型\n    DynamicJsonDocument act(128);\n    deserializeJson(act, cmd);\n    String action = act[\"action\"];\n    int sec = act[\"seconds\"] | 2;\n    if (action == \"forward\") forward();      // 复用路线A的电机函数\n    else if (action == \"back\") back();\n    else if (action == \"left\") left();\n    else if (action == \"right\") right();\n    else stop();\n    delay(sec * 1000); stop();        // 跑指定秒数后自动停（安全）\n  }\n}"}]},{"type":"heading","attrs":{"level":2,"align":null},"content":[{"type":"text","text":"七、组装步骤"}]},{"type":"task_list","content":[{"type":"task_item","attrs":{"checked":false},"content":[{"type":"paragraph","attrs":{"align":null},"content":[{"type":"text","text":"先用面包板让两个电机能正反转（不接语音），确认 TB6612 接线方向"}]}]},{"type":"task_item","attrs":{"checked":false},"content":[{"type":"paragraph","attrs":{"align":null},"content":[{"type":"text","text":"接 SU-03T：在「智能公元」建产品、加中文指令（前进/后退/左转/右转/停）、烧录固件"}]}]},{"type":"task_item","attrs":{"checked":false},"content":[{"type":"paragraph","attrs":{"align":null},"content":[{"type":"text","text":"串口收到命令 ID → 驱动对应动作，低速验证四个方向（路线 A 先跑通）"}]}]},{"type":"task_item","attrs":{"checked":false},"content":[{"type":"paragraph","attrs":{"align":null},"content":[{"type":"text","text":"联网调通 C3 → 大模型 API：说话 → 返回 JSON → 驱电机（路线 B）"}]}]},{"type":"task_item","attrs":{"checked":false},"content":[{"type":"paragraph","attrs":{"align":null},"content":[{"type":"text","text":"加 WS2812 状态灯、DFPlayer 儿歌作为语音反馈"}]}]},{"type":"task_item","attrs":{"checked":false},"content":[{"type":"paragraph","attrs":{"align":null},"content":[{"type":"text","text":"3D 打印/纸盒做软包边外壳，封死小件，只留麦克风孔和轮子空间"}]}]},{"type":"task_item","attrs":{"checked":false},"content":[{"type":"paragraph","attrs":{"align":null},"content":[{"type":"text","text":"电池接入，限速 + 自动停（收「停」或超时自动停）"}]}]},{"type":"task_item","attrs":{"checked":false},"content":[{"type":"paragraph","attrs":{"align":null},"content":[{"type":"text","text":"给娃试玩，观察他最爱哪个词，再多加几首儿歌"}]}]}]},{"type":"heading","attrs":{"level":2,"align":null},"content":[{"type":"text","text":"八、给 2 岁宝宝的注意事项"}]},{"type":"bullet_list","content":[{"type":"list_item","content":[{"type":"paragraph","attrs":{"align":null},"content":[{"type":"text","text":"车速要慢（PWM 调低），加软包边/防撞条，避免夹手夹脚。"}]}]},{"type":"list_item","content":[{"type":"paragraph","attrs":{"align":null},"content":[{"type":"text","text":"自动停止：收到「停」或 3 秒无指令自动停；加一个超声波避障更稳。"}]}]},{"type":"list_item","content":[{"type":"paragraph","attrs":{"align":null},"content":[{"type":"text","text":"电池用带保护的 "},{"type":"text","marks":[{"type":"code"}],"text":"TP4056"},{"type":"text","text":"，电池仓螺丝固定，防娃抠开（参考 EN71-1 / GB6675）。"}]}]},{"type":"list_item","content":[{"type":"paragraph","attrs":{"align":null},"content":[{"type":"text","text":"若走路线 B 用云端大模型，注意语音文本会发到服务商；介意就改路线 C 本地 Ollama，数据不出家门。"}]}]},{"type":"list_item","content":[{"type":"paragraph","attrs":{"align":null},"content":[{"type":"text","text":"整机圆角、无锐边，所有小件封进外壳，避免误吞。"}]}]}]},{"type":"callout","attrs":{"type":"success"},"content":[{"type":"paragraph","attrs":{"align":null},"content":[{"type":"text","text":"做完这台小车，娃喊一声「前进」，它真往前走——这大概是他第一次「用话指挥东西」，比任何买来的玩具都值得记住。"}]}]},{"type":"heading","attrs":{"level":2,"align":null},"content":[{"type":"text","text":"语音识别还有哪些解法（不只有 SU-03T）"}]},{"type":"paragraph","attrs":{"align":null},"content":[{"type":"text","text":"前面用 "},{"type":"text","marks":[{"type":"code"}],"text":"SU-03T"},{"type":"text","text":" 当「耳朵」只是最省事的一条路。给 C3 加语音识别其实有 6 条思路，核心区别在于三件事："},{"type":"text","marks":[{"type":"strong"}],"text":"识别在哪儿算、要不要额外芯片、联不联网、中文效果如何"},{"type":"text","text":"。"}]},{"type":"callout","attrs":{"type":"warning"},"content":[{"type":"paragraph","attrs":{"align":null},"content":[{"type":"text","text":"先泼盆冷水：ESP32-C3 既跑不了大模型，也跑不了「多命令词」的本地识别。乐鑫官方 ESP-SR 里，"},{"type":"text","marks":[{"type":"code"}],"text":"唤醒词模型 WakeNet（9s/10s）"},{"type":"text","text":" 已经能在「无 PSRAM、无 SIMD」的 C3 上常驻监听；但"},{"type":"text","marks":[{"type":"strong"}],"text":"命令词识别 MultiNet 目前只支持 ESP32-S3 / P4 / S31"},{"type":"text","text":"。也就是说——C3 端侧只能做「唤醒」，真正听懂「前进/后退」要么靠离线语音芯片，要么靠云端或家里的电脑。"}]}]},{"type":"table","content":[{"type":"table_row","content":[{"type":"table_header","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"align":null},"content":[{"type":"text","text":"方案"}]}]},{"type":"table_header","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"align":null},"content":[{"type":"text","text":"识别在哪跑"}]}]},{"type":"table_header","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"align":null},"content":[{"type":"text","text":"额外硬件"}]}]},{"type":"table_header","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"align":null},"content":[{"type":"text","text":"离线"}]}]},{"type":"table_header","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"align":null},"content":[{"type":"text","text":"中文"}]}]},{"type":"table_header","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"align":null},"content":[{"type":"text","text":"难度"}]}]},{"type":"table_header","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"align":null},"content":[{"type":"text","text":"适合娃 ★"}]}]}]},{"type":"table_row","content":[{"type":"table_cell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"align":null},"content":[{"type":"text","text":"① 离线语音芯片（SU-03T / VC-02 / SEN0539）"}]}]},{"type":"table_cell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"align":null},"content":[{"type":"text","text":"芯片内部"}]}]},{"type":"table_cell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"align":null},"content":[{"type":"text","text":"需买模块"}]}]},{"type":"table_cell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"align":null},"content":[{"type":"text","text":"是"}]}]},{"type":"table_cell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"align":null},"content":[{"type":"text","text":"需定制词"}]}]},{"type":"table_cell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"align":null},"content":[{"type":"text","text":"低"}]}]},{"type":"table_cell","attrs":{"colspan":1,"rowspan":1,"col