1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"align":null},"content":[{"type":"text","text":"中高"}]}]},{"type":"table_cell","attrs":{"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"align":null},"content":[{"type":"text","text":"★★★"}]}]}]}]},{"type":"heading","attrs":{"level":3,"align":null},"content":[{"type":"text","text":"路线②：乐鑫 ESP-SR 端侧唤醒（C3 本地）"}]},{"type":"paragraph","attrs":{"align":null},"content":[{"type":"text","text":"不买语音芯片，直接用 C3 跑乐鑫开源的 "},{"type":"text","marks":[{"type":"code"}],"text":"ESP-SR"},{"type":"text","text":" 框架：WakeNet 做 always-listening 唤醒词，VAD 做人声检测。C3 没有 PSRAM 和 SIMD 也能跑 WakeNet9s/10s，内存占用约 180KB Flash + 40KB RAM。唤醒后可以走两条分支：要么唤醒后短语音送云识别（见④），要么唤醒后直接由离线芯片/手机接管。"},{"type":"text","marks":[{"type":"strong"}],"text":"注意"},{"type":"text","text":"：MultiNet 多命令词识别在 C3 上跑不了，想要「本地听懂多句话+不联网」得换 ESP32-S3。"}]},{"type":"heading","attrs":{"level":3,"align":null},"content":[{"type":"text","text":"路线③：家里电脑跑本地 ASR（完全离线）"}]},{"type":"paragraph","attrs":{"align":null},"content":[{"type":"text","text":"C3 用 I2S 麦克风（如 INMP441）采音频，经 WiFi 把音频流送到家里常开的一台机器（旧电脑 / 树莓派 / x86 小主机），由它跑离线 ASR："},{"type":"text","marks":[{"type":"strong"}],"text":"Vosk"},{"type":"text","text":"（中文模型约 40–50MB，树莓派 3B 就能跑，流式延迟 ~50ms，Apache 2.0 开源）、"},{"type":"text","marks":[{"type":"strong"}],"text":"Whisper.cpp"},{"type":"text","text":"（精度高但实时性偏慢）、"},{"type":"text","marks":[{"type":"strong"}],"text":"Sherpa-onnx"},{"type":"text","text":"（中文效果好且自带 TTS，可顺带让小车开口说话）。识别结果再以 UDP/HTTP 回传给 C3 执行。数据不出家门，隐私最好，也最「AI」。"}]},{"type":"heading","attrs":{"level":3,"align":null},"content":[{"type":"text","text":"路线④：云端 ASR（百度 / 讯飞 / 阿里）"}]},{"type":"paragraph","attrs":{"align":null},"content":[{"type":"text","text":"C3 + I2S 麦克风采集音频并编码，直接 POST 给云端语音识别接口，返回文字后再丢给大模型当「大脑」（呼应前文路线 B）。国内三家都有可观的免费额度，且已有 "},{"type":"text","marks":[{"type":"strong"}],"text":"ESP32 直连百度智能云短语音识别的实测案例"},{"type":"text","text":"。缺点：依赖网络、有延迟、语音文本会发到服务商（介意就走路线③本地）。"}]},{"type":"heading","attrs":{"level":3,"align":null},"content":[{"type":"text","text":"路线⑤：手机 / 浏览器中转（开发最简单）"}]},{"type":"paragraph","attrs":{"align":null},"content":[{"type":"text","text":"不折腾 C3 端的麦克风与编码——让手机用系统自带的识别（或微信小程序、浏览器 Web Speech API）把话转成文字，再经 WiFi / BLE 发给 C3 执行。中文效果最好、开发成本最低，适合先快速验证「说话→小车动作」的整条链路。C3 这边只管收指令、跑电机。"}]},{"type":"callout","attrs":{"type":"success"},"content":[{"type":"paragraph","attrs":{"align":null},"content":[{"type":"text","marks":[{"type":"strong"}],"text":"给 2 岁娃的推荐组合："},{"type":"text","text":"想要零延迟、纯离线、最稳——选 ① SU-03T 离线芯片；想要「真能听懂任意话」又不想花钱/出户——选 C3 + I2S 麦 + 家里树莓派跑 ③ Vosk；想要效果最好、不怕联网——选 C3 + I2S 麦 + ④ 百度 ASR + 直连大模型（前文路线 B）。三条路都能和「SU-03T 当耳朵 + 大模型当大脑 + C3 当手脚」的架构衔接。"}]}]},{"type":"heading","attrs":{"level":2,"align":null},"content":[{"type":"text","text":"参考链接"}]},{"type":"bullet_list","content":[{"type":"list_item","content":[{"type":"paragraph","attrs":{"align":null},"content":[{"type":"text","marks":[{"type":"link","attrs":{"href":"https://www.printables.com/model/1798744","title":null}}],"text":"N20 Robot Car（Printables）"}]}]},{"type":"list_item","content":[{"type":"paragraph","attrs":{"align":null},"content":[{"type":"text","marks":[{"type":"link","attrs":{"href":"https://bit-tree.com/cn/product/product-52-160.html","title":null}}],"text":"SU-03T 离线语音模组（bit-tree）"}]}]},{"type":"list_item","content":[{"type":"paragraph","attrs":{"align":null},"content":[{"type":"text","marks":[{"type":"link","attrs":{"href":"https://www.dfrobot.com/product-2665.html","title":null}}],"text":"DFRobot Gravity 离线语音传感器 SEN0539"}]}]},{"type":"list_item","content":[{"type":"paragraph","attrs":{"align":null},"content":[{"type":"text","marks":[{"type":"link","attrs":{"href":"http://smartpi.cn","title":null}}],"text":"智能公元平台（SU-03T 固件配置）"}]}]},{"type":"list_item","content":[{"type":"paragraph","attrs":{"align":null},"content":[{"type":"text","marks":[{"type":"link","attrs":{"href":"https://api-docs.deepseek.com","title":null}}],"text":"DeepSeek API 文档"}]}]},{"type":"list_item","content":[{"type":"paragraph","attrs":{"align":null},"content":[{"type":"text","marks":[{"type":"link","attrs":{"href":"https://help.aliyun.com/zh/model-studio/","title":null}}],"text":"阿里云百炼 / 通义千问 API"}]}]},{"type":"list_item","content":[{"type":"paragraph","attrs":{"align":null},"content":[{"type":"text","marks":[{"type":"link","attrs":{"href":"https://ollama.com","title":null}}],"text":"Ollama（本地模型，局域网调用）"}]}]},{"type":"list_item","content":[{"type":"paragraph","attrs":{"align":null},"content":[{"type":"text","marks":[{"type":"link","attrs":{"href":"https://www.printables.com/model/1623405","title":null}}],"text":"TonyBox（Printables）"}]}]},{"type":"list_item","content":[{"type":"paragraph","attrs":{"align":null},"content":[{"type":"text","marks":[{"type":"link","attrs":{"href":"https://galmakes.com/project/musical-keyboard","title":null}}],"text":"Michael''s Musical Keyboard（GalMakes）"}]}]}]}]},"createdAt":"2026-10-27T08:12:58.880Z","updatedAt":"2026-10-27T10:58:01.076Z","lastVisitedAt":"2026-11-10T01:38:15.558Z","parentId":"a3a23c8a9b31","ownerId":"6b7a7531b0f8","acl":{"visibility":"private","members":{},"inherit":true},"canEdit":true,"canManage":true,"visibility":"private","inherit":true,"favorite":false,"pinned":false,"pinnedAt":null},{"id":"a3a23c8a9b31","title":"物联网","content":{"type":"doc","content":[{"type":"paragraph","attrs":{"align":null}}]},"parentId":null,"favorite":false,"lastVisitedAt":"2026-11-09T12:41:05.519Z","createdAt":"2026-11-02T05:56:05.101Z","updatedAt":"2026-11-04T06:49:44.525Z","ownerId":"6b7a7531b0f8","acl":{"visibility":"private","members":{},"inherit":true},"canEdit":true,"canManage":true,"visibility":"private","inherit":true,"pinned":false,"pinnedAt":null},{"id":"40c0058a8433","title":"2026 双十一买什么：把国补用对的清单（11.02 更新）","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":1,"align":null},"content":[{"type":"text","text":"2026 双十一买什么：把「国补」用对的清单"}]},{"type":"paragraph","attrs":{"align":null},"content":[{"type":"text","text":"写于 "},{"type":"text","marks":[{"type":"strong"}],"text":"2026 年 11 月 2 日"},{"type":"text","text":"，距 11 月 10 日晚 8 点的全场高潮还有 8 天。今年是双十一的第 18 年，规则比往年简单，但"},{"type":"text","marks":[{"type":"strong"}],"text":"真正拉开差价的环节从平台换到了国补"},{"type":"text","text":"——算错这一步，其他券都白领。"}]},{"type":"callout","attrs":{"type":"success"},"content":[{"type":"paragraph","attrs":{"align":null},"content":[{"type":"text","text":"一句话结论：先确认自己想换什么，再去核验国补资格，最后等 11 月 10 日晚 8 点下单。不要为了「便宜」凭空创造需求，今年的折扣没有大到能让闲置变得合理。"}]}]},{"type":"heading","attrs":{"level":2,"align":null},"content":[{"type":"text","text":"一、今年最大的三个变化"}]},{"type":"ordered_list","attrs":{"order":1},"content":[{"type":"list_item","content":[{"type":"paragraph","attrs":{"align":null},"content":[{"type":"text","marks":[{"type":"strong"}],"text":"不用凑单了。"},{"type":"text","text":" 天猫把主推玩法换成「官方立减」，京东是「官方直降」，单件成交就降价，不必为了满减塞进一堆不需要的东西。跨店满减是否还参与因类目而异，以商品页为准。"}]}]},{"type":"list_item","content":[{"type":"paragraph","attrs":{"align":null},"content":[{"type":"text","marks":[{"type":"strong"}],"text":"国补成了主战场。"},{"type":"text","text":" 第四批（也是今年最后一批）消费品以旧换新资金已下达，双十一期间额度相对充足，但按省管控、先到先得，热门型号会先耗尽。"}]}]},{"type":"list_item","content":[{"type":"paragraph","attrs":{"align":null},"content":[{"type":"text","marks":[{"type":"strong"}],"text":"战线拉长到 11 月 13 日。"},{"type":"text","text":" 京东 10 月 12 日起、天猫 10 月 15 日起，现货窗口一路开到 11 月 13 日，不用死守 11 号那一天。"}]}]}]},{"type":"table","content":[{"type":"table_row","content":[{"type":"table_header","attrs":{"colspan":1,"rowspan":1,"colwidth":[140]},"content":[{"type":"paragraph","attrs":{"align":null},"content":[{"type":"text","text":"节点"}]}]},{"type":"table_header","attrs":{"colspan":1,"rowspan":1,"colwidth":[380]},"content":[{"type":"paragraph","attrs":{"align":null},"content":[{"type":"text","text":"京东"}]}]},{"type":"table_header","attrs":{"colspan":1,"rowspan":1,"colwidth":[380]},"content":[{"type":"paragraph","attrs":{"align":null},"content":[{"type":"text","text":"天猫 / 淘宝"}]}]}]},{"type":"table_row","content":[{"type":"table_cell","attrs":{"colspan":1,"rowspan":1,"colwidth":[140]},"content":[{"type":"paragraph","attrs":{"align":null},"content":[{"type":"text","text":"开始"}]}]},{"type":"table_cell","attrs":{"colspan":1,"rowspan":1,"colwidth":[380]},"content":[{"type":"paragraph","attrs":{"align":null},"content":[{"type":"text","text":"10/12 红包上线"}]}]},{"type":"table_cell","attrs":{"colspan":1,"rowspan":1,"colwidth":[380]},"content":[{"type":"paragraph","attrs":{"align":null},"content":[{"type":"text","text":"10/15 预售 + 红包"}]}]}]},{"type":"table_row","content":[{"type":"table_cell","attrs":{"colspan":1,"rowspan":1,"colwidth":[140]},"content":[{"type":"paragraph","attrs":{"align":null},"content":[{"type":"text","text":"第一波"}]}]},{"type":"table_cell","attrs":{"colspan":1,"rowspan":1,"colwidth":[380]},"content":[{"type":"paragraph","attrs":{"align":null},"content":[{"type":"text","text":"10/20 20:00 开门红现货"}]}]},{"type":"table_cell","attrs":{"colspan":1,"rowspan":1,"colwidth":[380]},"content":[{"type":"paragraph","attrs":{"align":null},"content":[{"type":"text","text":"10/20 20:00 尾款 + 现货"}]}]}]},{"type":"table_row","content":[{"type":"table_cell","attrs":{"colspan":1,"rowspan":1,"colwidth":[140]},"content":[{"type":"paragraph","attrs":{"align":null},"content":[{"type":"text","text":"高潮"}]}]},{"type":"table_cell","attrs":{"colspan":1,"rowspan":1,"colwidth":[380]},"content":[{"type":"paragraph","attrs":{"align":null},"content":[{"type":"text","text":"11/10 20:00 – 11/11 24:00"}]}]},{"type":"table_cell","attrs":{"colspan":1,"rowspan":1,"colwidth":[380]},"content":[{"type":"paragraph","attrs":{"align":null},"content":[{"type":"text","text":"11/10 20:00 – 11/11 24:00"}]}]}]},{"type":"table_row","content":[{"type":"table_cell","attrs":{"colspan":1,"rowspan":1,"colwidth":[140]},"content":[{"type":"paragraph","attrs":{"align":null},"content":[{"type":"text","text":"返场"}]}]},{"type":"table_cell","attrs":{"colspan":1,"rowspan":1,"colwidth":[380]},"content":[{"type":"paragraph","attrs":{"align":null},"conte